from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=[]
for i,p in enumerate(r.pages,1):
    for a in p.get('/Annots',[]):
        obj=a.get_object()
        act=obj.get('/A')
        if act and act.get('/URI'):
            links.append((i,str(act['/URI'])))
for i,uri in links:
    if any(k in uri.lower() for k in ['github','zenodo','osf','code','drive.google']):
        print(i,uri)
